program_src='''from collections import deque


def transform(grid):
    g = [row[:] for row in grid]
    height, width = len(g), len(g[0])
    sr, sc = next((r, c) for r in range(height) for c in range(width) if g[r][c] == 2)
    if sr == 0:
        dr, dc = 1, 0
    elif sr == height - 1:
        dr, dc = -1, 0
    elif sc == 0:
        dr, dc = 0, 1
    elif sc == width - 1:
        dr, dc = 0, -1
    else:
        raise ValueError("marker must be on a boundary")

    queue = deque([(sr, sc, dr, dc)])
    seen = set()

    def inside(r, c):
        return 0 <= r < height and 0 <= c < width

    while queue:
        r, c, dr, dc = queue.popleft()
        if (r, c, dr, dc) in seen:
            continue
        seen.add((r, c, dr, dc))
        rr, cc = r + dr, c + dc
        while inside(rr, cc) and g[rr][cc] != 8:
            if g[rr][cc] == 0:
                g[rr][cc] = 2
            rr, cc = rr + dr, cc + dc
        if not inside(rr, cc):
            continue

        # Follow the wall from the cell just before it, stopping at the
        # first opening in each direction and continuing through that opening.
        ar, ac = rr - dr, cc - dc
        for step in (-1, 1):
            x, y = ar, ac
            while inside(x, y):
                if g[x][y] == 0:
                    g[x][y] = 2
                wr, wc = x + dr, y + dc
                if not inside(wr, wc):
                    break
                if g[wr][wc] != 8:
                    if g[wr][wc] == 0:
                        g[wr][wc] = 2
                    queue.append((wr, wc, dr, dc))
                    break
                x, y = x + step * dc, y + step * dr
    return g
'''
